using Finance.Core;
using System.Data;
namespace Finance.Desktop;
internal partial class MainForm
{
    static readonly Dictionary<string,string> Labels=new(){["GSTIN"]="GSTIN",["StateCode"]="GST state code (2 digits)",["JoinDay"]="Joining date",["LeaveDay"]="Leaving date",["Salary"]="Monthly salary (INR)",["EPF"]="EPF applicable",["ESIC"]="ESIC applicable",["IPNumber"]="ESIC IP number",["ShowLogo"]="Show logo on documents",["LogoPosition"]="Logo position",["StartDay"]="Start date",["EndDay"]="End date",["PartyId"]="Customer (optional)",["Rate"]="Default rate (INR)",["GSTRate"]="Default GST %",["Cash"]="Cash account",["Active"]="Active",["HSN"]="HSN / SAC",["CreditDays"]="Credit days"};
    void Masters(){var bar=Bar();var selector=new ComboBox{Width=210,DropDownStyle=ComboBoxStyle.DropDownList};selector.Items.AddRange(new object[]{"Company","Customer","Supplier","Employee","Bank","Site","Item","Category"});selector.SelectedIndex=0;var grid=Ui.Grid();DataTable raw=new();
        string Table()=>selector.Text is "Customer" or "Supplier"?"Party":selector.Text;
        void Load(){using var d=engine.Open();string table=Table();string cols=table=="Company"?"Id,"+string.Join(',',Engine.MasterFields[table]):"*";raw=d.Table($"SELECT {cols} FROM {table}"+(table=="Party"?" WHERE Kind=@p0":"")+" ORDER BY Id DESC LIMIT 500",selector.Text);var display=raw.Clone();foreach(DataColumn c in display.Columns)c.DataType=typeof(string);foreach(DataRow r in raw.Rows){var row=display.NewRow();foreach(DataColumn c in raw.Columns){var value=r[c];row[c.ColumnName]=value is DBNull?"":c.ColumnName.EndsWith("Day")?Value.Date((int)Value.Long(value)):c.ColumnName is "Salary" or "Rate"?Value.Display(Value.Long(value)):Value.Text(value);}display.Rows.Add(row);}grid.DataSource=display;}
        long Selected(){Value.Require(grid.CurrentRow!=null,"Select a master record.");return Value.Long(grid.CurrentRow!.Cells["Id"].Value);}
        bar.Controls.Add(selector);bar.Controls.Add(Ui.Button("+ Add",()=>{MasterEdit(selector.Text);Load();}));bar.Controls.Add(Ui.Button("Edit",()=>{MasterEdit(selector.Text,Selected());Load();}));bar.Controls.Add(Ui.Button("Attachments",()=>{Value.Require(selector.Text=="Employee","Select Employee to manage employee attachments.");Attachments("Employee",Selected());}));bar.Controls.Add(Ui.Button("Company logo",Logo,130));selector.SelectedIndexChanged+=(_,_)=>Ui.Run(Load);content.Controls.Add(grid);content.Controls.Add(bar);Title("Master data","Opening balances are controlled transactions under Settings. First 500 records shown.");Load();}
    void MasterEdit(string kind,long? id=null){string table=kind is "Customer" or "Supplier"?"Party":kind;if(table=="Company")id=1;Dictionary<string,object?> initial=[];using(var d=engine.Open())if(id!=null){var row=d.Row($"SELECT * FROM {table} WHERE Id=@p0",id);initial=row.Table.Columns.Cast<DataColumn>().ToDictionary(c=>c.ColumnName,c=>(object?)row[c]);}
        using var f=new Entry("Master • "+kind,initial);foreach(var key in Engine.MasterFields[table]){
            if(key=="Kind")continue;string label=Labels.GetValueOrDefault(key,key);object? def=key=="Active"?1:key=="GSTRate"?"18":key=="Currency"?"INR":null;
            if(key.EndsWith("Day"))f.Add(key,label,"date",optional:key!="JoinDay");
            else if(key is "Salary" or "Rate")f.Add(key,label,"money");else if(key is "EPF" or "ESIC" or "Active" or "Cash" or "ShowLogo")f.Add(key,label,"bool",value:def);
            else if(key=="CreditDays")f.Add(key,label,"number");else if(key=="GSTRate")f.Add(key,label,"percent",value:def);
            else if(key=="PartyId")f.Add(key,label,choices:Choices("Party","Kind='Customer'"),optional:true);
            else if(key=="LogoPosition")f.Add(key,label,options:["Left","Centre","Right"]);else if(key=="Status")f.Add(key,label,options:["Active","Completed","On Hold"]);
            else f.Add(key,label,key is "Address" or "Remarks" or "Description"?"multiline":"text",value:def);
        }
        f.Finish(x=>{var vals=x.Values();if(table=="Party")vals["Kind"]=kind;engine.SaveMaster(table,vals,id);});f.ShowDialog(this);
    }
    void Logo(){using var f=new Form{Text="Company logo",Width=550,Height=400,StartPosition=FormStartPosition.CenterParent};var pic=new PictureBox{Dock=DockStyle.Fill,SizeMode=PictureBoxSizeMode.Zoom,BackColor=Color.White};void Load(){using var d=engine.Open();pic.Image?.Dispose();var bytes=d.Scalar("SELECT Logo FROM Company WHERE Id=1") as byte[];if(bytes!=null){using var ms=new MemoryStream(bytes);using var img=Image.FromStream(ms);pic.Image=new Bitmap(img);}else pic.Image=null;}var bar=Bar();bar.Controls.Add(Ui.Button("Upload / replace",()=>{using var open=new OpenFileDialog{Filter="Logo|*.png;*.jpg;*.jpeg"};if(open.ShowDialog()!=DialogResult.OK)return;var bytes=File.ReadAllBytes(open.FileName);Value.Require(bytes.Length<=5000000,"Logo must be below 5 MB.");using var ms=new MemoryStream(bytes);using var img=Image.FromStream(ms,true,true);Value.Require(img.Width<=10000&&img.Height<=10000,"Logo dimensions must be below 10,000 pixels.");engine.SetLogo(bytes);Load();},150));bar.Controls.Add(Ui.Button("Remove",()=>{Confirm("Remove company logo?",()=>engine.SetLogo(null));Load();}));f.Controls.Add(pic);f.Controls.Add(bar);Load();f.ShowDialog(this);pic.Image?.Dispose();}
    void Settings(){var panel=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,AutoScroll=true};panel.Controls.Add(Ui.Button("Statutory settings",Statutory,260));panel.Controls.Add(Ui.Button("Opening balance",Opening,260));panel.Controls.Add(Ui.Button("Lock / unlock period",()=>{using var f=new Entry("Period control");f.Add("From","From date","date");f.Add("To","To date","date");f.Add("Lock","Action",options:["Lock","Unlock"]);f.Add("Reason","Reason","multiline");f.Finish(x=>Confirm("Apply period lock change?",()=>engine.Lock(x.D("From"),x.D("To"),x.S("Lock")=="Lock",x.S("Reason"))));f.ShowDialog(this);},260));panel.Controls.Add(Ui.Button("Financial year",()=>{using var f=new Entry("Financial year");f.Add("Year","Financial year starting year","number",value:DateTime.Today.Month>=4?DateTime.Today.Year:DateTime.Today.Year-1);f.Finish(x=>{int year=x.D("Year");Value.Require(year is >=1900 and <=2199,"Select a valid starting year.");from.Value=new DateTime(year,4,1);to.Value=new DateTime(year+1,3,31);engine.SetSetting("FinancialYear",$"{year}-{year+1}");Footer();});f.ShowDialog(this);},260));panel.Controls.Add(Ui.Button("Voucher numbering",()=>{using var f=new Entry("Voucher prefixes");f.Add("Kind","Voucher type",options:["Receipt","Payment","Bank Transfer","Site Expense","Payroll","Employee Loan","FD","Opening","Reversal"]);f.Add("Prefix","Prefix");f.Finish(x=>engine.SetSetting("Prefix."+x.S("Kind"),x.S("Prefix")));f.ShowDialog(this);},260));panel.Controls.Add(Ui.Button("Change password",()=>{using var f=new Entry("Change password");f.Add("Old","Current password","password");f.Add("New","New password","password");f.Add("Again","Confirm new password","password");f.Finish(x=>{Value.Require(x.S("New")==x.S("Again"),"Passwords do not match.");engine.ChangePassword(x.S("Old"),x.S("New"));});f.ShowDialog(this);},260));panel.Controls.Add(Ui.Button("Database integrity",()=>MessageBox.Show(engine.Integrity()),260));panel.Controls.Add(new Label{Text="Opening balances carry forward through the ledger automatically; do not re-enter them each year.\nStatutory settings are effective-dated. The supplied defaults are configurable, not a legal compliance certification.",Width=700,Height=90,Margin=new Padding(5,20,0,0)});content.Controls.Add(panel);Title("Settings and controls");}
    void Statutory(){using var d=engine.Open();var r=d.Row("SELECT * FROM Statutory ORDER BY EffectiveDay DESC LIMIT 1");var init=r.Table.Columns.Cast<DataColumn>().ToDictionary(c=>c.ColumnName,c=>(object?)r[c]);init["EffectiveDay"]=new DateOnly(DateTime.Today.Year,DateTime.Today.Month,1).DayNumber;using var f=new Entry("New statutory setting — retains history",init);f.Add("EffectiveDay","Effective from (month start)","date");foreach(var k in new[]{"BasicPercent","EPFRate","ESICRate"})f.Add(k,k+" %","percent");f.Add("EPFCeiling","EPF wage ceiling (INR)","money");f.Add("CapEPF","Apply EPF ceiling","bool");f.Add("EPFBasis","EPF wage basis",options:["Basic","Gross"]);f.Add("ESICCeiling","ESIC eligibility ceiling (INR)","money");f.Add("ESICBasis","ESIC contribution basis",options:["Basic","Gross"]);foreach(var key in new[]{"EPFRounding","ESICRounding","SalaryRounding"})f.Add(key,key,options:["Paise","Rupee","Ceiling"]);f.Finish(x=>engine.SaveStatutory(new(x.D("EffectiveDay"),x.Dec("BasicPercent"),x.Dec("EPFRate"),x.N("EPFCeiling"),x.N("CapEPF")==1,x.S("EPFBasis"),x.Dec("ESICRate"),x.N("ESICCeiling"),x.S("ESICBasis"),x.S("EPFRounding"),x.S("ESICRounding"),x.S("SalaryRounding"))));f.ShowDialog(this);}
    void Opening(){using var d=engine.Open();using var f=new Entry("Controlled opening balance");f.Add("Day","Effective date","date");f.Add("Account","Ledger",options:d.Table("SELECT Code FROM Account WHERE Category IN ('Asset','Liability','Equity') AND Code<>'OPEN'").Rows.Cast<DataRow>().Select(r=>Value.Text(r[0])));f.Add("Amount","Amount (INR)","money");f.Add("Side","Balance side",options:["Debit","Credit"]);f.Add("Party","Customer / supplier",choices:Choices("Party"),optional:true);f.Add("Employee","Employee",choices:Choices("Employee"),optional:true);f.Add("Bank","Bank / cash",choices:Choices("Bank"),optional:true);f.Add("Site","Site",choices:Choices("Site"),optional:true);f.Add("Instrument","Existing FD / loan",choices:Choices("Instrument"),optional:true);f.Add("Reason","Opening balance reference","multiline");f.Finish(x=>{Value.Require(x.N("Amount")>0,"Amount must be positive.");engine.Opening(x.D("Day"),[new(x.S("Account"),x.N("Amount")*(x.S("Side")=="Debit"?1:-1),x.Id("Party"),x.Id("Employee"),x.Id("Bank"),x.Id("Site"),x.Id("Instrument"))],x.S("Reason"));});f.ShowDialog(this);}
    void BackupScreen(){var p=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown};p.Controls.Add(Ui.Button("Backup now",()=>{using var folder=new FolderBrowserDialog();if(folder.ShowDialog()==DialogResult.OK){var path=engine.Backup(folder.SelectedPath);lastBackup=DateTime.Now;Footer();MessageBox.Show("Backup saved and verified:\n"+path);}},280));p.Controls.Add(Ui.Button("Automatic backup",()=>{using var folder=new FolderBrowserDialog{Description="Choose automatic backup folder"};if(folder.ShowDialog()!=DialogResult.OK)return;using var f=new Entry("Automatic backup");f.Add("Minutes","Interval in minutes","number",value:60);f.Finish(x=>{engine.SetSetting("BackupFolder",folder.SelectedPath);engine.SetSetting("BackupMinutes",x.S("Minutes"));});f.ShowDialog(this);},280));p.Controls.Add(Ui.Button("Restore backup",()=>{using var open=new OpenFileDialog{Filter="Business Finance backup|*.db"};if(open.ShowDialog()!=DialogResult.OK)return;Confirm("Restore this backup? A verified copy of the current database will be saved first. The app will close and you must sign in using the backup's account.",()=>{var protectedCopy=engine.Restore(open.FileName);MessageBox.Show("Restore completed. Previous database saved at:\n"+protectedCopy);Close();});},280));p.Controls.Add(Ui.Button("Backup history",()=>{content.Controls.Clear();Register("Backup History");},280));p.Controls.Add(new Label{Text="Automatic backups run while this application is open.\nBackups include the database, company logo and all attachments.\nStore a separate copy outside this computer. Backups are not encrypted.",Width=700,Height=100,Margin=new Padding(5,18,0,0)});content.Controls.Add(p);Title("Backup and restore");}
    void AutoBackup(){try{using var d=engine.Open();string folder=Value.Text(d.Scalar("SELECT Value FROM Setting WHERE Key='BackupFolder'"));int minutes=int.TryParse(Value.Text(d.Scalar("SELECT Value FROM Setting WHERE Key='BackupMinutes'")),out var m)?m:60;if(folder!=""&&DateTime.Now-lastBackup>=TimeSpan.FromMinutes(minutes)){engine.Backup(folder);lastBackup=DateTime.Now;Footer();}}catch(Exception ex){lastBackup=DateTime.Now;status.Text="Automatic backup failed or session expired. Use Backup now after signing in. "+Ui.Credit;File.AppendAllText(System.IO.Path.Combine(System.IO.Path.GetDirectoryName(engine.Path)!,"backup-errors.log"),DateTime.Now.ToString("O")+" "+ex+Environment.NewLine);}}
}
